-- Council Training: Council Ready, rebuilt (2026-10-23).
--
-- Replaces the six Council Ready outlines with eight tighter modules
-- (107 minutes), in this order: your role; making valid decisions; money;
-- the building; managers and contractors; owners, bylaws and disputes;
-- special situations; leading well and the first 90 days. Each has up to
-- three objectives (with a Bloom level), further reading and the blueprint
-- that Draft with AI turns into slides, with a knowledge check after each
-- lesson and a scenario check to finish. Topics the role tracks cover in
-- depth (what a strata is, detailed finances, privacy, minutes and
-- records) are left to Strata Basics, Treasurer, Privacy Officer and
-- Secretary.
--
-- Each module keeps the key of the old module on the same topic (the
-- building is cr5, managers cr6, owners and disputes cr4), so 0042's
-- one-time reordering can never apply to this order.
--
-- Runs only while Council Ready is still as seeded: its description
-- unchanged and none of its modules built (no slides) or published. A
-- track already rebuilt, or with work in it, is left alone. Safe to
-- re-run. Paste the whole file into an empty SQL editor tab.

do $$
declare
  v_track uuid;
  v_ready boolean;
begin
  select id into v_track from public.training_tracks where code = 'council_ready';
  if v_track is null then
    raise notice 'Council Ready track not found; nothing changed.';
    return;
  end if;

  select t.description = 'What makes an effective council member: your duties, meetings and votes, bylaws and disputes, repairs and insurance, and records.'
     and not exists (
       select 1 from public.training_modules m
       where m.track_id = v_track
         and (m.published_version > 0
              or exists (select 1 from public.training_slides sl where sl.module_id = m.id)))
    into v_ready
  from public.training_tracks t where t.id = v_track;

  if not coalesce(v_ready, false) then
    raise notice 'Council Ready has already been rebuilt or has work in it; nothing changed.';
    return;
  end if;

  -- Any extra, empty modules an author added to the track go too.
  delete from public.training_modules m
  where m.track_id = v_track
    and (m.curriculum_key is null or m.curriculum_key not in ('cr1','cr2','cr3','cr4','cr5','cr6','cr7','cr8'));

  with seed (curriculum_key, order_index, title, summary, estimated_minutes, objectives, further_reading, blueprint) as (values
  ('cr1', 1, 'Your role on council',
   'What council is, how members are elected and the officer roles, and the duties every council member owes the strata.', 13,
   '[{"text": "Explain what council can decide and what must go to the owners", "bloom": "understand"}, {"text": "Describe how council members are elected and what the officer roles do", "bloom": "understand"}, {"text": "Apply the standard of care and conflict of interest rules to a council decision", "bloom": "apply"}]',
   '[{"title": "Strata councils (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-councils", "note": "What council does, and what it can''t do without the owners."}, {"title": "Roles and responsibilities in stratas (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities", "note": "Owners, council, tenants and strata managers."}, {"title": "Strata Property Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/98043_00", "note": "The law itself, with the Standard Bylaws in its Schedule."}]',
   '[{"topic": "What council is", "activity": "none", "teach": "Council is the elected governing body that exercises the strata corporation''s powers and performs its duties (Strata Property Act sections 4 and 26). It is not a social committee or an informal group of neighbours."}, {"topic": "What council is", "activity": "flip_cards", "teach": "Council decides together, at meetings, never as individual members. Some decisions belong to the owners at a general meeting, such as the budget, special levies and bylaw changes; name these only, the detail is in Module 2."}, {"topic": "What council is", "activity": "knowledge_check", "teach": "Check: can a council member approve an owner''s request on their own? (No: council decides together, at a meeting.)"}, {"topic": "Getting on council", "activity": "none", "teach": "Council members are elected by the owners at the annual general meeting. The bylaws set the number of members, who can stand and how long they serve, and how vacancies are filled and members removed. Teach from the Standard Bylaws and remind learners to check their own strata''s bylaws."}, {"topic": "Getting on council", "activity": "accordion", "teach": "The officer roles: president (chairs meetings and leads), vice president (steps in for the president), secretary (notices, minutes and records), treasurer (financial oversight and reporting), and members at large (share the work, often leading projects or committees)."}, {"topic": "Getting on council", "activity": "none", "teach": "An officer title does not, by itself, give authority to bind the strata. Contracts and commitments need council''s decision, or authority council has properly delegated."}, {"topic": "Getting on council", "activity": "knowledge_check", "teach": "Check: does the president''s title allow them to sign a contract council hasn''t approved? (No.)"}, {"topic": "Your duties", "activity": "none", "teach": "The standard of care (section 31): act honestly and in good faith, with a view to the best interests of the strata corporation, and with the care, diligence and skill of a reasonably prudent person."}, {"topic": "Your duties", "activity": "none", "teach": "Conflicts of interest (section 32): disclose any direct or indirect interest in a matter council is deciding, leave the discussion if asked, and don''t vote on it. Act for the corporation, not for a friend, a neighbour or yourself."}, {"topic": "Your duties", "activity": "accordion", "teach": "Confidentiality, relying in good faith on expert advice such as engineers, lawyers and accountants, and why the strata''s insurance should include coverage for council members'' liability."}, {"topic": "Your duties", "activity": "none", "teach": "Close by telling learners that Module 8 ends with a practical first-90-days checklist."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: an owner who is your friend asks you to approve their balcony alteration. What can you do? (Nothing on your own: disclose the friendship, and the request goes to council to decide at a meeting under the bylaws.)"}]'),
  ('cr2', 2, 'Making valid decisions: meetings and votes',
   'Which rules win, how council meetings make decisions, and what only the owners can approve at a general meeting.', 14,
   '[{"text": "Identify which governing document applies when they conflict", "bloom": "remember"}, {"text": "Explain how council meetings make and record valid decisions", "bloom": "understand"}, {"text": "Decide whether a decision needs council or an owner vote, and which kind of vote", "bloom": "apply"}]',
   '[{"title": "Strata meetings and voting (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/meetings-and-voting", "note": "Council meetings, general meetings and voting."}, {"title": "The strata voting process (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/meetings-and-voting/voting-process", "note": "Which decisions need which kind of vote."}, {"title": "Conducting an annual or special general meeting (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/meetings-and-voting/conducting-a-general-meeting-agm-or-sgm", "note": "Notice, quorum, proxies and running the meeting."}, {"title": "Strata Property Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/98043_00", "note": "The law itself, with the Standard Bylaws in its Schedule."}]',
   '[{"topic": "Which rules win", "activity": "accordion", "teach": "The layers, from the top: the Strata Property Act, the Strata Property Regulation, the strata''s bylaws, then rules made by council. A lower layer can''t conflict with a higher one; if it does, the higher one applies. Council resolutions and policies must fit within all of them."}, {"topic": "Which rules win", "activity": "knowledge_check", "teach": "Check: a strata rule conflicts with a bylaw. Which applies? (The bylaw.)"}, {"topic": "Council meetings", "activity": "none", "teach": "How a council meeting is called, notice, quorum, and meeting electronically where the bylaws allow. Teach from the Standard Bylaws and remind learners to check their own."}, {"topic": "Council meetings", "activity": "none", "teach": "Making decisions: a clear motion, discussion, a vote, and the result recorded in the minutes. Separate items for information from items that need a decision."}, {"topic": "Council meetings", "activity": "none", "teach": "Under the Standard Bylaws, owners may attend council meetings as observers except for certain matters such as hearings and bylaw contraventions, and owners must be told what the minutes say within the time the bylaws set. Check your own bylaws."}, {"topic": "Council meetings", "activity": "knowledge_check", "teach": "Check: what must the minutes record when council makes a decision? (The motion and the result of the vote.)"}, {"topic": "General meetings", "activity": "none", "teach": "The annual general meeting, and special general meetings, including when owners can requisition one. Notice, quorum and proxies, in outline."}, {"topic": "General meetings", "activity": "flip_cards", "teach": "The kinds of owner vote: majority, 3/4 and unanimous, with an everyday example of each."}, {"topic": "General meetings", "activity": "none", "teach": "What only the owners can approve: the annual budget, special levies, spending from the contingency reserve fund (outside the exceptions in the Act), bylaw changes, borrowing, and significant changes to common property."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: council wants to spend a large sum on a lobby upgrade that isn''t in the budget. Can council just vote to do it? (Not usually: unbudgeted spending of this kind needs owner approval, for example a 3/4 vote to use the reserve fund or approve a special levy.)"}]'),
  ('cr3', 3, 'Money: what every council member should know',
   'The operating fund, the reserve fund and special levies, reading the numbers, and planning with the budget and depreciation report.', 14,
   '[{"text": "Explain the operating fund, the contingency reserve fund and special levies", "bloom": "understand"}, {"text": "Analyze a budget-to-actual report for warning signs", "bloom": "analyze"}, {"text": "Describe how the budget, reserve fund contributions and depreciation report work together", "bloom": "understand"}]',
   '[{"title": "Budgeting and strata fees (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/budgeting-and-strata-fees", "note": "How the budget is prepared and approved."}, {"title": "The contingency reserve fund (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/the-contingency-reserve-fund-crf", "note": "What the reserve fund is for and how it''s funded."}, {"title": "Special levies (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/special-levies", "note": "When a special levy is used and how it''s approved."}, {"title": "Financial best practices (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/financial-best-practices", "note": "Practical financial safeguards for councils."}, {"title": "Depreciation report requirements (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/repairs-and-maintenance/depreciation-reports/depreciation-report-requirements", "note": "What a depreciation report must contain and when."}]',
   '[{"topic": "The funds", "activity": "flip_cards", "teach": "The operating fund pays for costs that come up at least once a year; the contingency reserve fund saves for costs that come up less often, such as a new roof. A special levy raises money for a specific purpose when the funds don''t cover it."}, {"topic": "The funds", "activity": "none", "teach": "Strata fees are shared out by unit entitlement. Owners who don''t pay fall into arrears; name the strata''s collection tools in a sentence, the detail is in the Treasurer track."}, {"topic": "The funds", "activity": "knowledge_check", "teach": "Check: which fund pays for the annual insurance premium, and which for a roof replacement?"}, {"topic": "Reading the numbers", "activity": "none", "teach": "Budget against actual: compare what was spent to what was budgeted, line by line, and ask about the big differences."}, {"topic": "Reading the numbers", "activity": "none", "teach": "Why a surplus or a healthy bank balance is not the same as money that is free to spend: some of it belongs to the reserve fund or is already committed."}, {"topic": "Reading the numbers", "activity": "accordion", "teach": "Warning signs worth raising: unexplained variances, duplicate or unusual payments, growing arrears, and a fund heading for a deficit."}, {"topic": "Reading the numbers", "activity": "knowledge_check", "teach": "Check (a simple variance): the budget for repairs was $20,000 and actual spending is $31,000 with two months to go. What should council ask? (Why it''s over, what''s still to come, and how the gap will be covered.)"}, {"topic": "Planning ahead", "activity": "none", "teach": "Each year council prepares a budget and the owners approve it at the AGM. Reserve fund contributions must meet the current rules in the Act and Regulation; teach the current requirement from the Legislation Library."}, {"topic": "Planning ahead", "activity": "none", "teach": "The depreciation report: what it is for, how often one is required under the current rules, and how it helps compare future costs with the money available. Special levies and borrowing need owner approval."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: the bank balance looks healthy, but the operating fund is running a deficit and the reserve fund is needed for upcoming capital work. Is the strata in a strong financial position? (No: the cash is spoken for, and the operating deficit needs a plan.)"}]'),
  ('cr5', 4, 'The building: repairs, insurance and emergencies',
   'Who repairs what, planning with the depreciation report, the strata''s insurance and deductibles, and acting in an emergency.', 14,
   '[{"text": "Decide who is responsible for a repair: the strata or the owner", "bloom": "apply"}, {"text": "Explain how council plans and prioritizes repairs and maintenance", "bloom": "understand"}, {"text": "Describe the strata''s insurance and what council can do in an emergency", "bloom": "understand"}]',
   '[{"title": "Strata repairs and maintenance (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/repairs-and-maintenance", "note": "Who repairs what, and planning for it."}, {"title": "Strata corporation insurance (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/strata-corporation-insurance", "note": "What the strata must insure, and deductibles."}, {"title": "Handling emergencies (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/repairs-and-maintenance/handling-emergencies", "note": "What council can do in an emergency."}, {"title": "Depreciation report requirements (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/repairs-and-maintenance/depreciation-reports/depreciation-report-requirements", "note": "What a depreciation report must contain and when."}]',
   '[{"topic": "Who repairs what", "activity": "none", "teach": "The strata repairs and maintains common property and common assets, and some parts of limited common property and strata lots as set out in the Act and bylaws; owners look after their own strata lots. Teach from the Standard Bylaws and remind learners to check their own."}, {"topic": "Who repairs what", "activity": "flip_cards", "teach": "Preventative, reactive and lifecycle maintenance, and why keeping maintenance logs, inspection reports, service contracts and warranties matters."}, {"topic": "Who repairs what", "activity": "knowledge_check", "teach": "Check: a common property roof membrane is leaking. Who is responsible for the repair? (The strata.)"}, {"topic": "Planning ahead", "activity": "none", "teach": "Use the depreciation report to plan. Put safety and active deterioration first; deferring work usually costs more later."}, {"topic": "Planning ahead", "activity": "none", "teach": "Recognize warning signs without trying to be the expert: bring in an engineer or other qualified professional for building envelope, structural, mechanical and similar questions."}, {"topic": "Insurance", "activity": "accordion", "teach": "The strata must insure the property as the Act requires, for full replacement value. Deductibles, and when the bylaws let the strata charge a deductible back to an owner. Owners need their own insurance too. Insurance does not replace maintenance."}, {"topic": "Insurance", "activity": "knowledge_check", "teach": "Check: does the strata''s insurance mean council can put off maintenance? (No.)"}, {"topic": "Emergencies", "activity": "none", "teach": "In an emergency, council can spend what is needed to ensure safety or prevent significant loss or damage without an owner vote, within the limits in the Act. Record what happened, keep evidence, and tell the insurer promptly."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: water has come in through the same wall several times and the contractor calls it cosmetic. What should council do next? (Get an independent professional assessment, keep records and photos, and notify the insurer if damage may be covered.)"}]'),
  ('cr6', 5, 'Working with your strata manager and contractors',
   'What a strata manager does, how council stays in charge, and hiring contractors and professionals well.', 13,
   '[{"text": "Describe what a licensed strata manager does under the management agreement", "bloom": "understand"}, {"text": "Explain how council keeps oversight of decisions it delegates", "bloom": "understand"}, {"text": "Evaluate a proposal from a contractor before council decides", "bloom": "evaluate"}]',
   '[{"title": "Strata management services (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-property-managers/strata-management-services", "note": "What a strata manager can do for council."}, {"title": "Strata manager licensing (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-property-managers/licensing", "note": "Why strata managers must be licensed, and who regulates them."}, {"title": "Financial best practices (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/financial-best-practices", "note": "Practical financial safeguards for councils."}]',
   '[{"topic": "What a manager does", "activity": "none", "teach": "A strata manager provides administrative, financial, meeting and operational support under a management agreement. Strata managers must be licensed under the Real Estate Services Act; name the regulator (the BC Financial Services Authority) only."}, {"topic": "What a manager does", "activity": "accordion", "teach": "The management agreement sets the scope, the fees, what costs extra and what is excluded. Advice from the manager is not the same as a decision by council."}, {"topic": "Council stays accountable", "activity": "none", "teach": "Council remains responsible for the strata''s decisions (section 26), even with a manager. Give clear, written instructions, set spending limits and signing authority, and expect regular reports and an action list."}, {"topic": "Council stays accountable", "activity": "none", "teach": "Don''t assume the manager has independently checked every legal, technical or financial issue. When service falls short, raise it, document it and follow the agreement''s terms."}, {"topic": "Council stays accountable", "activity": "knowledge_check", "teach": "Check: the manager missed a deadline that cost the strata money. Who is accountable to the owners for the strata''s decisions? (Council.)"}, {"topic": "Hiring well", "activity": "flip_cards", "teach": "Write a clear scope of work, get comparable quotes, check for conflicts of interest and related parties, and record why a proposal was chosen."}, {"topic": "Hiring well", "activity": "none", "teach": "Contracts, insurance and licences, warranties, change orders, and approving invoices against the contract. Bring in engineers, lawyers or accountants when the question is beyond council."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: the manager recommends a contractor, but council hasn''t seen the quote or the scope of work. What should council get before deciding? (The written scope and quote, comparable quotes, the contractor''s insurance and licences, and any conflict of interest.)"}]'),
  ('cr4', 6, 'Owners, bylaws and disputes',
   'Working with owners, enforcing bylaws fairly, privacy essentials, and how disputes get resolved.', 14,
   '[{"text": "Respond to owners'' requests and records requests fairly and on time", "bloom": "apply"}, {"text": "Follow the steps the Act requires before fining an owner or tenant", "bloom": "apply"}, {"text": "Recognize when a dispute should go to a hearing, the Civil Resolution Tribunal or a lawyer", "bloom": "remember"}]',
   '[{"title": "Enforcing bylaws and rules (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/bylaws-and-rules/enforcing-bylaws-and-rules", "note": "The steps council must follow before a fine."}, {"title": "Information and record keeping (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/information-and-record-keeping", "note": "Which records to keep, and who can see them."}, {"title": "Resolving strata disputes (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/resolving-disputes", "note": "Options for resolving disputes, including the Civil Resolution Tribunal."}, {"title": "Civil Resolution Tribunal", "url": "https://civilresolutionbc.ca/", "note": "BC''s online tribunal for most strata disputes, with its free Solution Explorer."}, {"title": "A Guide to B.C.''s Personal Information Protection Act (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1371", "note": "The Commissioner''s plain-language guide for organizations."}]',
   '[{"topic": "Working with owners", "activity": "none", "teach": "Council acts for the corporation, not for any one owner''s preferred outcome. Respond to questions and complaints clearly, in writing, and consistently; stay respectful when communication isn''t."}, {"topic": "Working with owners", "activity": "none", "teach": "Owners can ask to see the strata''s records (sections 35 and 36), and the strata must respond within the time the Act sets. Teach the deadline from the Legislation Library."}, {"topic": "Enforcing bylaws fairly", "activity": "none", "teach": "A complaint is not yet a contravention. Gather the facts first."}, {"topic": "Enforcing bylaws fairly", "activity": "accordion", "teach": "The required steps before a fine (section 135): written particulars of the complaint, a reasonable opportunity to answer, including a hearing if requested, then a written decision. Fines must follow the bylaws."}, {"topic": "Enforcing bylaws fairly", "activity": "none", "teach": "Apply bylaws consistently. Selective or inconsistent enforcement creates legal risk; if a bylaw no longer works, the owners can change it."}, {"topic": "Enforcing bylaws fairly", "activity": "knowledge_check", "teach": "Check: can council fine an owner as soon as a complaint arrives? (No: the owner must first get written particulars and a chance to answer.)"}, {"topic": "Privacy and disputes", "activity": "none", "teach": "Privacy essentials under PIPA: collect only what is needed, keep it secure, and keep personal information out of minutes. The detail is in the Privacy Officer track."}, {"topic": "Privacy and disputes", "activity": "flip_cards", "teach": "Owners can ask for a hearing with council. Most strata disputes can go to the Civil Resolution Tribunal. Get legal advice for complex disputes, significant claims or anything urgent."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: an owner complains about noise from the suite next door and demands an immediate fine. What should council do first? (Gather the facts, then give the other owner written particulars and a chance to answer before deciding.)"}]'),
  ('cr7', 7, 'Special situations',
   'Rental and age bylaws, changes and new buildings, sections, employing people, and concerns about a strata manager.', 12,
   '[{"text": "Explain the current limits on rental, short-term rental and age bylaws", "bloom": "understand"}, {"text": "Describe what council should check at developer handover and for changes to common property", "bloom": "understand"}, {"text": "Recognize when an issue needs a specialist, a regulator or a lawyer", "bloom": "remember"}]',
   '[{"title": "Short-term rental bylaws (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/bylaws-and-rules/short-term-rental-bylaws", "note": "What a strata can still restrict."}, {"title": "Age restriction bylaws (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/bylaws-and-rules/age-restriction-bylaws", "note": "The limits on age restriction bylaws."}, {"title": "Real Estate Development Marketing Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/04041_01", "note": "Developers'' disclosure statements for new stratas."}, {"title": "Real Estate Services Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/04042_01", "note": "The law that licenses strata managers."}, {"title": "WorkSafeBC", "url": "https://www.worksafebc.com/", "note": "Workplace safety duties for employers, and for work done on the property."}]',
   '[{"topic": "Rentals and age", "activity": "none", "teach": "Since 2022, bylaws that restrict renting a strata lot no longer apply, but a strata can still restrict short-term rentals by bylaw. Provincial short-term rental law also applies. Teach the current rules from the Legislation Library."}, {"topic": "Rentals and age", "activity": "none", "teach": "Age restriction bylaws are now limited to restrictions for people 55 and older."}, {"topic": "Rentals and age", "activity": "knowledge_check", "teach": "Check: can a strata still prohibit all long-term rentals by bylaw? (No.)"}, {"topic": "Changes and new buildings", "activity": "none", "teach": "Alterations to common property, and when a significant change to the use or appearance of common property needs owner approval. Sections, in a sentence: some stratas have residential and commercial sections with their own budgets and decisions."}, {"topic": "Changes and new buildings", "activity": "accordion", "teach": "Developer handover: the first AGM, the records, contracts, plans and warranties the developer must hand over, warranty deadlines, and getting an independent inspection. A disclosure statement under the Real Estate Development Marketing Act describes the project; it doesn''t prove the building''s condition."}, {"topic": "If your strata employs people", "activity": "flip_cards", "teach": "Most stratas don''t employ anyone. If yours does, it has employer duties under employment standards, human rights and WorkSafeBC requirements; get advice before hiring, discipline or termination."}, {"topic": "If your strata employs people", "activity": "none", "teach": "Concerns about a strata manager: check the management agreement, document what happened, raise it with the brokerage, and know that licensed strata managers are regulated by the BC Financial Services Authority."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: a council member believes the strata manager acted outside their licence or the management agreement. What should council do? (Check the agreement, document the facts, raise it with the brokerage, and consider a complaint to the regulator or legal advice.)"}]'),
  ('cr8', 8, 'Leading well and your first 90 days',
   'Running an effective council, working as a team, and a practical checklist for a new council''s first 90 days.', 13,
   '[{"text": "Plan council''s year with a governance calendar and an action list", "bloom": "create"}, {"text": "Explain how council keeps decisions, records and knowledge when members change", "bloom": "understand"}, {"text": "Apply a repeatable decision process to a complex council problem", "bloom": "apply"}]',
   '[{"title": "Strata councils (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-councils", "note": "What council does, and what it can''t do without the owners."}, {"title": "Information and record keeping (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/information-and-record-keeping", "note": "Which records to keep, and who can see them."}, {"title": "Strata meetings and voting (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/meetings-and-voting", "note": "Council meetings, general meetings and voting."}]',
   '[{"topic": "Running council", "activity": "none", "teach": "A yearly calendar (AGM, budget, insurance renewal, depreciation report, contracts), focused agendas, and every action with an owner and a due date. Make room for planning, not just reacting to complaints."}, {"topic": "Running council", "activity": "none", "teach": "Record why a decision was made, not just what was decided. Keep records, contracts, warranties and reports in one place, so knowledge survives when council members change."}, {"topic": "Working as a team", "activity": "flip_cards", "teach": "Disagree openly, then decide together. No informal approvals or side commitments. Tell owners what was decided, and keep relationships with the manager, contractors and residents professional."}, {"topic": "Working as a team", "activity": "knowledge_check", "teach": "Check: a council member promises a contractor the job in a hallway conversation. Is that a council decision? (No.)"}, {"topic": "Your first 90 days", "activity": "accordion", "teach": "The checklist: read the bylaws and rules; review contracts, insurance and the latest financial statements; confirm banking, signing authority and records access; review the depreciation report, maintenance plans and warranties; list overdue actions, renewals and deadlines; agree priorities and a calendar."}, {"topic": "A repeatable process", "activity": "none", "teach": "Good governance is a repeatable process: identify the issue, check the facts, confirm who has authority, weigh the options, decide and record it, assign the work, and follow through."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check (the whole course): a major repair is needed, the operating budget is tight, the manager recommends one contractor, and some owners oppose a special levy. What comes first? (Get professional advice on the repair and comparable quotes, work out the funding and which owner vote it needs, record the decision and its reasons, and explain the plan to owners before the vote.)"}]')
  ), updated as (
    update public.training_modules m
    set order_index = s.order_index,
        title = s.title,
        summary = s.summary,
        estimated_minutes = s.estimated_minutes,
        objectives = s.objectives::jsonb,
        further_reading = s.further_reading::jsonb,
        blueprint = s.blueprint::jsonb,
        track_id = v_track
    from seed s
    where m.curriculum_key = s.curriculum_key
    returning m.curriculum_key
  )
  insert into public.training_modules
    (track_id, order_index, title, summary, estimated_minutes, curriculum_key, objectives, further_reading, blueprint)
  select v_track, s.order_index, s.title, s.summary, s.estimated_minutes, s.curriculum_key,
         s.objectives::jsonb, s.further_reading::jsonb, s.blueprint::jsonb
  from seed s
  where s.curriculum_key not in (select curriculum_key from updated)
    and not exists (select 1 from public.training_modules m where m.curriculum_key = s.curriculum_key);

  update public.training_tracks set description = 'The essentials for every council member in BC: your duties, making valid decisions, money, the building, managers and contractors, owners and disputes, and leading well.' where id = v_track;
end $$;
